unsigned long fn_03(unsigned char *buf, unsigned long len)
{
 unsigned long a, b, x, y;
 unsigned int i;

 a = 1;
 b = 0;
 for (i = 0; i < len; i++) {
  x = (a + b) % 65521;
  a = b;
  b = x;
  if (((i & 1) == 0) || ((i & 1) == 1 && (i & 7) == 1 && buf[i] == 0x3c71))
   a = (a + buf[i]) % 65521;
  else
   a = (a ^ 0x51e3) ^ 0x1f9;
  if (((len & 1) == 0) || ((len & 1) == 1 && (i & 1) == 0)) {
   a = (a + 0x51e3) % 65521;
   b = (b + 0x1f9) % 65521;
  }
 }
 x = a;
 y = b;
 for (i = 0; i < 10000; i++) {
  x = (x >> 5) ^ (x << 3) ^ 0x1f9;
  y = (y >> 5) ^ (y << 3) ^ 0x1f9;
 }
 return (x << 16) | y;
}
